// Task instructions:
// Build a complete RBAC system for a blog platform. Roles: admin, editor, author, reader. Permissions: create/edit/delete/publish posts, manage users, m...

solution_code:
// middleware/rbac.js

// Role-based middleware
export function requireRole(...roles) {
  return (req, res, next) => {
    if (!req.user) {
      const err = new Error('Authentication required');
      err.statusCode = 401;
      return next(err);
    }

    if (!roles.includes(req.user.role)) {
      const err = new Error('Insufficient permissions');
      err.statusCode = 403;
      return next(err);
    }

    next();
  };
}

// Permission-based middleware
const ROLE_PERMISSIONS = {
  admin: ['user:read', 'user:write', 'user:delete',
          'post:read', 'post:write', 'post:delete',
          'comment:read', 'comment:write', 'comment:delete'],
  moderator: ['user:read', 'post:read', 'post:write',
              'comment:read', 'comment:write', 'comment:delete'],
  user: ['post:read', 'post:write', 'comment:read', 'comment:write'],
  guest: ['post:read', 'comment:read']
};

export function requirePermission(...permissions) {
  return (req, res, next) => {
    if (!req.user) {
      const err = new Error('Authentication required');
      err.statusCode = 401;
      return next(err);
    }

    const userPermissions = ROLE_PERMISSIONS[req.user.role] || [];
    const hasPermission = permissions.every(p =>
      userPermissions.includes(p)
    );

    if (!hasPermission) {
      const err = new Error('Insufficient permissions');
      err.statusCode = 403;
      return next(err);
    }

    next();
  };
}

// Resource ownership check
export function requireOwnership(getResourceUserId) {
  return async (req, res, next) => {
    try {
      const resourceUserId = await getResourceUserId(req);
      if (
        req.user.role !== 'admin' &&
        req.user.id !== resourceUserId
      ) {
        const err = new Error('You can only modify your own resources');
        err.statusCode = 403;
        return next(err);
      }
      next();
    } catch (err) { next(err); }
  };
}
